{"cards": [{"node_code": "N_dd507807b8779743", "definition": "研究由病原体（细菌、病毒、真菌、寄生虫等）引起的脑、脊髓及脑膜感染性疾病，以及累及周围神经的感染性病变。", "boundary": "涵盖脑膜炎、脑炎、脑脓肿、脊髓炎及周围神经炎等感染性病因。与“周围神经疾病”的区别在于本节点强调感染性病因，而后者侧重非感染性（如代谢、遗传、压迫）病因。与“神经免疫病”的区别在于本节点侧重病原体直接侵袭，后者侧重自身免疫机制。", "includes": ["细菌性、病毒性、真菌性及寄生虫性脑膜炎与脑炎", "中枢神经系统感染引起的脊髓病变", "感染性周围神经炎（如莱姆病神经病变）"], "excludes": ["非感染性周围神经病变（主挂周围神经疾病）", "自身免疫性脑炎（主挂发作性与神经免疫病）"], "sibling_distinctions": [{"other_code": "N_7697f4fdd43d2cd5", "rule": "本节点收录感染性病因导致的周围神经病；兄弟节点收录非感染性（代谢、遗传、压迫等）周围神经病。"}, {"other_code": "N_39852d944b97e0c7", "rule": "本节点侧重病原体直接感染；兄弟节点侧重自身免疫介导的神经炎症（如自身免疫性脑炎）。"}], "cross_boundary_rule": "若感染性疾病伴随显著自身免疫反应，需结合神经免疫病；若为术后或医源性感染，需结合外科学或感染科。"}, {"node_code": "N_39852d944b97e0c7", "definition": "研究以阵发性、重复性神经功能异常为特征的发作性疾病，以及由自身免疫机制介导的神经系统炎症性疾病。", "boundary": "涵盖癫痫、偏头痛、睡眠障碍等发作性疾病，以及多发性硬化、吉兰-巴雷综合征、自身免疫性脑炎等神经免疫病。与“中枢神经系统感染”的区别在于本节点侧重非感染性免疫机制或功能性发作。与“脱髓鞘疾病”存在交叉，但本节点更强调免疫病理机制及发作性特征。", "includes": ["癫痫及癫痫综合征的诊断与治疗", "自身免疫性脑炎、视神经脊髓炎谱系疾病", "吉兰-巴雷综合征及慢性炎性脱髓鞘性多发性神经病"], "excludes": ["由明确病原体引起的脑炎（主挂中枢神经系统感染与周围神经病）", "遗传性周期性麻痹（主挂神经遗传与发育疾病）"], "sibling_distinctions": [{"other_code": "N_dd507807b8779743", "rule": "本节点侧重自身免疫机制或非感染性发作；兄弟节点侧重病原体直接感染。"}, {"other_code": "N_c40ec59607d58fa1", "rule": "本节点涵盖所有神经免疫病（含脱髓鞘与非脱髓鞘）；兄弟节点专指脱髓鞘病理机制的疾病，若内容侧重免疫机制可主挂本节点。"}], "cross_boundary_rule": "脱髓鞘疾病若强调免疫治疗或自身免疫背景，可关联本节点；若仅描述病理形态，主挂脱髓鞘疾病。"}, {"node_code": "N_7697f4fdd43d2cd5", "definition": "研究非感染性病因引起的周围神经、神经根、神经丛及神经肌肉接头的结构与功能异常疾病。", "boundary": "涵盖糖尿病性神经病变、遗传性神经病、压迫性神经病（如腕管综合征）、中毒性神经病及神经肌肉接头疾病（如重症肌无力）。与“中枢神经系统感染与周围神经病”的区别在于本节点排除感染性病因。与“神经肌肉疾病”的区别在于本节点侧重神经纤维本身，后者侧重肌肉及运动单位。", "includes": ["代谢性、遗传性及中毒性周围神经病", "压迫性、外伤性及炎性非感染性周围神经病", "神经肌肉接头疾病（如重症肌无力、Lambert-Eaton综合征）"], "excludes": ["感染性周围神经炎（主挂中枢神经系统感染与周围神经病）", "原发性肌肉疾病（主挂神经肌肉疾病）"], "sibling_distinctions": [{"other_code": "N_dd507807b8779743", "rule": "本节点收录非感染性周围神经病；兄弟节点收录感染性周围神经病。"}, {"other_code": "N_d3b72eda06d215a3", "rule": "本节点侧重周围神经及神经肌肉接头；兄弟节点侧重肌肉本身及肌病。"}], "cross_boundary_rule": "若周围神经病由全身系统性疾病（如糖尿病、尿毒症）引起，需结合相关内科节点，但神经病理主挂本节点。"}]}
